"use client";

/**
 * Header with search trigger, notifications and the user menu.
 *
 * Must call (do not reimplement): isEnabled
 */
import { Button } from "@/components/ui/button";
import { isEnabled } from "@/lib/feature-flags";
import { orgFlagContext } from "@/hooks/flag-context";
import { formatShortcut } from "@/hooks/shortcut-match";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor, User } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { ReactElement } from "react";
import { NotificationBell } from "../notification/notification-bell";
import { UserMenu } from "./user-menu";

export type TopBarProps = {
  org: Organization;
  actor: Actor;
  unreadCount: number;
  flags: FeatureFlagSnapshot;
  /** The signed-in user record, for the avatar menu. */
  user?: User;
  onOpenSearch?: () => void;
  onSignOut?: () => void;
};

export function TopBar(props: TopBarProps): ReactElement | null {
  const { org, actor, unreadCount, flags, user, onOpenSearch, onSignOut } =
    props;

  const context = orgFlagContext(org, actor);
  const paletteOn =
    flags.command_palette === true || isEnabled("command_palette", context);
  const advancedSearchOn =
    flags.advanced_search === true || isEnabled("advanced_search", context);

  return (
    <header className="top-bar flex items-center justify-between gap-3 border-b px-4 py-2">
      <span className="font-semibold">{org.name}</span>

      <div className="flex flex-1 justify-center">
        {paletteOn ? (
          <Button variant="secondary" size="sm" onClick={onOpenSearch}>
            {advancedSearchOn ? "Search issues, comments, projects" : "Search"}
            <span className="ml-2 text-xs text-neutral-500">
              {formatShortcut(["mod", "k"])}
            </span>
          </Button>
        ) : null}
      </div>

      <div className="flex items-center gap-2">
        <NotificationBell unreadCount={unreadCount} orgSlug={org.slug} />
        {user !== undefined ? (
          <UserMenu
            user={user}
            orgSlug={org.slug}
            onSignOut={onSignOut ?? (() => undefined)}
          />
        ) : null}
      </div>
    </header>
  );
}
"use client";

/**
 * Client-side plumbing for feature flags.
 *
 * The server evaluates every flag once per request with `snapshotFlags()` and
 * serialises the result into `FeatureFlagProvider`. The client therefore reads
 * the snapshot rather than re-deriving anything — but when a key is missing
 * (a snapshot serialised before a newly shipped flag existed) we fall back to
 * `isEnabled()` so there is still exactly one evaluator in the codebase.
 */
import { createContext } from "react";
import { isEnabled } from "@/lib/feature-flags";
import type {
  FeatureFlagKey,
  FeatureFlagSnapshot,
  FlagContext,
} from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";

/** Context for a signed-out / pre-hydration reader: free plan, no role. */
export const ANONYMOUS_FLAG_CONTEXT: FlagContext = {
  orgId: null,
  userId: null,
  plan: "free",
  role: null,
};

/** The full evaluation context for a member browsing one organization. */
export function orgFlagContext(org: Organization, actor: Actor): FlagContext {
  return {
    orgId: org.id,
    userId: actor.userId,
    plan: org.plan,
    role: actor.role,
    overrides: org.settings.enabledFlagOverrides,
  };
}

/**
 * Reads one flag out of a server-evaluated snapshot, falling back to a live
 * `isEnabled()` evaluation when the snapshot predates the flag.
 */
export function readFlag(
  snapshot: FeatureFlagSnapshot | null,
  flag: FeatureFlagKey,
  context: FlagContext = ANONYMOUS_FLAG_CONTEXT,
): boolean {
  const evaluated = snapshot?.[flag];
  return typeof evaluated === "boolean"
    ? evaluated
    : isEnabled(flag, context);
}

export const FlagSnapshotContext = createContext<FeatureFlagSnapshot | null>(
  null,
);

