/** Token bucket protecting the index from query bursts. */
const SEARCH_QUERY_BUCKET = "search:query";

/** Without `advanced_search` only issues are searched (ADR 0007 rule 4). */
const BASIC_SEARCH_KINDS: readonly SearchSubjectKind[] = ["issue"];

/**
 * Runs a query against the denormalised index (ADR 0007). The query is parsed
 * with the dialog's parser: with `advanced_search`, `kind:` / `in:` and
 * `project:` tokens narrow the search; without it the whole query, colons
 * included, is literal text and only issues are searched. This service is the
 * gate — callers pass the query and their requested kinds straight through.
 */
export async function search(
  actor: Actor,
  input: SearchQueryInput,
): Promise<Page<SearchHit>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));

  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Search rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await orgRepo.findOrgById(input.orgId);
  const advanced = isEnabled("advanced_search", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  const parsed = parseSearchQuery(input.q, advanced);
  const text = parsed.text;
  const projectId = parsed.projectId ?? input.projectId;
  const page = await searchRepo.searchDocuments({
    ...input,
    q: text,
    kinds: [...searchedKinds(input.kinds, parsed, advanced)],
    ...(projectId !== undefined ? { projectId } : {}),
  });

  return {
    items: page.items.map((row) => ({
      kind: row.subjectKind,
      id: row.subjectId,
      title: row.content.split("\n")[0] ?? row.subjectId,
      snippet: snippetAround(row.content, text),
      href: hrefFor(row.subjectKind, row.subjectId),
    })),
    nextCursor: page.nextCursor,
    total: page.total,
  };
}

/**
 * Which kinds a query covers: issues only without `advanced_search`; with it,
 * any `kind:` tokens decide, otherwise the caller's kinds are honoured.
 */
function searchedKinds(
  requested: readonly SearchSubjectKind[],
  parsed: ParsedSearchQuery,
  advanced: boolean,
): readonly SearchSubjectKind[] {
  if (!advanced) return BASIC_SEARCH_KINDS;
  return parsed.explicitKinds ? parsed.kinds : requested;
}

