import * as searchService from "@/server/services/search-service";
import * as searchRepo from "@/server/repositories/search-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { getDb, searchIndex } from "@/server/db";
import { createTenant, issueInput, useTemporaryDatabase } from "$P/tests/server/_support/fixtures";

let cleanup: () => void;
let detach: () => void;
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
});
afterAll(() => { detach(); cleanup(); });

const q = (t: any, text: string, extra: any = {}) =>
  searchService.search(t.actors.member, { orgId: t.org.id, q: text, kinds: ["issue", "comment", "project"], limit: 25, cursor: null, ...extra });

describe("reports", () => {
  it("1: starter colon query is literal", async () => {
    const t = await createTenant("rep1", "starter");
    const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "Release 2: hotfix" }));
    const r = await q(t, "Release 2: hotfix");
    expect(r.total).toBe(1);
    expect(r.items[0].id).toBe(issue.id);
    expect((await q(t, "kind:comment hotfix")).total).toBe(0);
  });

  it("2/3: enterprise tokens narrow, project scope includes comments", async () => {
    const t = await createTenant("rep2", "enterprise");
    const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "flaky deploy issue" }));
    const c = await commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: issue.id, body: "this is flaky deploy", parentId: null, mentionedUserIds: [] });
    let r = await q(t, "kind:comment flaky", { kinds: ["issue"] });
    expect(r.items.map((h) => h.id)).toEqual([c.id]);
    r = await q(t, "in:comments flaky");
    expect(r.items.map((h) => h.id)).toEqual([c.id]);
    r = await q(t, \`project:\${t.project.id} deploy\`);
    expect(r.items.map((h) => h.kind).sort()).toEqual(["comment", "issue"]);
    r = await q(t, "deploy", { projectId: t.project.id });
    expect(r.total).toBe(2);
    r = await q(t, "label:x flaky");
    expect(r.total).toBe(2);
    r = await q(t, "kind: flaky");
    expect(r.total).toBe(2);
    // Edit keeps project id and new text
    const edited = await commentService.updateComment(t.actors.member, { orgId: t.org.id, commentId: c.id, body: "now stable deploy" });
    expect(edited.body).toBe("now stable deploy");
    r = await q(t, "stable", { projectId: t.project.id });
    expect(r.items.map((h) => h.id)).toEqual([c.id]);
    // rebuild fixes null project ids
    getDb().update(searchIndex).set({ projectId: null }).run();
    expect((await q(t, "stable", { projectId: t.project.id })).total).toBe(0);
    const job = await runSearchReindexJob(t.org.id);
    expect(job.failed ?? 0).toBe(0);
    expect((await q(t, "stable", { projectId: t.project.id })).total).toBe(1);
  });

  it("4: wildcards are literal", async () => {
    const t = await createTenant("rep4", "growth");
    await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "snake case" }));
    await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "SNAKE_CASE thing" }));
    await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "coverage at 100% now" }));
    await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "path a\\\\b" }));
    expect((await q(t, "100%")).total).toBe(1);
    expect((await q(t, "snake_case")).total).toBe(1);
    expect((await q(t, "a\\\\b")).total).toBe(1);
    expect((await q(t, "%")).total).toBe(1);
  });

  it("5: growth palette gets issues only", async () => {
    const t = await createTenant("rep5", "growth");
    const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "palette target" }));
    await commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: issue.id, body: "palette target comment", parentId: null, mentionedUserIds: [] });
    const r = await q(t, "palette");
    expect(r.total).toBe(1);
    expect(r.items.map((h) => h.kind)).toEqual(["issue"]);
    // override enables advanced search
    await orgRepo.updateOrg?.(t.org.id, { settings: { ...t.org.settings, enabledFlagOverrides: ["advanced_search"] } } as any).catch(() => undefined);
  });

  it("6: reindex request covers every kind and skips archived", async () => {
    const t = await createTenant("rep6", "enterprise");
    const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "reindex issue" }));
    const c = await commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: issue.id, body: "reindex comment", parentId: null, mentionedUserIds: [] });
    await searchRepo.deleteSearchDocument(t.org.id, "comment", c.id);
    await searchRepo.deleteSearchDocument(t.org.id, "project", t.project.id);
    expect((await q(t, "reindex comment")).total).toBe(0);
    await emit("search.reindex_requested", { orgId: t.org.id, actorId: null, subjectKind: "comment", subjectId: c.id } as any);
    await emit("search.reindex_requested", { orgId: t.org.id, actorId: null, subjectKind: "project", subjectId: t.project.id } as any);
    let r = await q(t, "reindex comment", { projectId: t.project.id });
    expect(r.items.map((h) => h.id)).toEqual([c.id]);
    r = await q(t, "rep6 platform");
    expect(r.items.map((h) => h.kind)).toEqual(["project"]);
    await issueService.archiveIssue(t.actors.member, t.org.id, issue.id);
    await emit("search.reindex_requested", { orgId: t.org.id, actorId: null, subjectKind: "issue", subjectId: issue.id } as any);
    expect((await q(t, "reindex issue")).total).toBe(0);
  });
});
